#include <cmath>
#include <iostream>
#include <numbers>
#include <print>
#include <string>

class Shape {
public:
    virtual double area() const {
        return 0;
    }

    virtual const char *name() const {
        return "фигура";
    }
};

class Rect : public Shape {
public:
    Rect(double w, double h) : w_(w), h_(h) {}

    double area() const override {
        return w_ * h_;
    }

    const char *name() const override {
        return "прямоугольник";
    }

private:
    double w_;
    double h_;
};

class Circle : public Shape {
public:
    explicit Circle(double r) : r_(r) {}

    double area() const override {
        return std::numbers::pi * r_ * r_;
    }

    const char *name() const override {
        return "круг";
    }

private:
    double r_;
};

class Triangle : public Shape {
public:
    Triangle(double a, double b, double c) : a_(a), b_(b), c_(c) {}

    double area() const override {
        double p = (a_ + b_ + c_) / 2;
        return std::sqrt(p * (p - a_) * (p - b_) * (p - c_));
    }

    const char *name() const override {
        return "треугольник";
    }

private:
    double a_;
    double b_;
    double c_;
};

double report(const Shape &s) {
    std::println("{}: {:.2f}", s.name(), s.area());
    return s.area();
}

int main() {
    std::string kind;
    double total = 0;
    while (std::cin >> kind) {
        if (kind == "rect") {
            double w, h;
            std::cin >> w >> h;
            total += report(Rect(w, h));
        } else if (kind == "circle") {
            double r;
            std::cin >> r;
            total += report(Circle(r));
        } else {
            double a, b, c;
            std::cin >> a >> b >> c;
            total += report(Triangle(a, b, c));
        }
    }
    std::println("всего: {:.2f}", total);
    return 0;
}

